USE customer_analysis;
#Q1. Total revenue generated by male vs female customers
SELECT 
    gender,
    SUM(purchase_amount) AS total_revenue
FROM shopping_data
GROUP BY gender;
#Q2. Customers who used discounts but spent more than average purchase amount
SELECT 
    customer_id,
    purchase_amount
FROM shopping_data
WHERE discount_applied = 'Yes'
AND purchase_amount > (
    SELECT AVG(purchase_amount)
    FROM shopping_data
);
